#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {         long long n, k, b, s;        cin >> n >> k >> b >> s;         long long minSum = b * k;        long long maxSum = b * k + (k - 1) * n;         if (s < minSum || s > maxSum) {            cout << -1 << "\n";            continue;        }         vector<long long> a(n, 0);         a[0] = b * k;         long long extra = s - b * k;         for (int i = 0; i < n && extra > 0; i++) {            long long add = min(extra, k - 1);            a[i] += add;            extra -= add;        }         for (auto x : a) cout << x << " ";        cout << "\n";    }}